noncomputable def VTask.piEquivPiSubtypeProd {α : Type u_9} (p : α → Prop) (β : α → Type u_10) [DecidablePred p] :
    ((i : α) → β i) ≃ ((i : { x // p x }) → β ↑i) × ((i : { x // ¬p x }) → β ↑i) :=
  let positive := { x // p x }
  let negative := { x // ¬p x }
  let to_fun (f : (i : α) → β i) : ((i : positive) → β ↑i) × ((i : negative) → β ↑i) :=
    (λ ⟨i, hi⟩, f i), λ ⟨i, hi⟩, f i)
  let inv_fun (g : ((i : positive) → β ↑i) × ((i : negative) → β ↑i)) : (i : α) → β i :=
    match g with
    | (g_pos, g_neg) => λ i, if p i then g_pos ⟨i, p i⟩ else g_neg ⟨i, ¬p i⟩
  let left_inv (f : (i : α) → β i) : to_fun (inv_fun (to_fun f)) = f :=
    funext $ λ i, by cases i; simp
  let right_inv (g : ((i : positive) → β ↑i) × ((i : negative) → β ↑i)) : inv_fun (to_fun (inv_fun g)) = g :=
    funext $ λ i, by cases i; simp
  Equiv.mk to_fun inv_fun left_inv right_inv
